1	// src/lib/fakten/schema.js
2	//
3	// VERTRAG des Faktenregisters (Welle 2, Paket B1). Jeder Markt- und Rechtswert der
4	// Website ist ein „Fakt“ mit Quelle, Stand, Gültigkeit, Status, Prüfer und Klasse.
5	// Dieser Vertrag gilt für alle Datenmodule unter src/lib/fakten/daten/ – auch für die
6	// Dateien anderer Pakete (FRI: termine-*, umlagen-*, netzentgelte-*; B4 liest nur).
7	// Änderungen am Vertrag nur abgestimmt mit FRI und B4.
8	//
9	// Fakt = {
10	//   id          string    Punkt-getrennt, klein beginnend, z. B. "pacht.freiflaecheProHa"
11	//                         (id + land ist eindeutig; dieselbe id kann es je Land geben)
12	//   wert        number | string | boolean | object | array | null
13	//                         Spannen als { min, mittel?, max }, Tabellen als Array.
14	//                         null nur für dokumentierte Lücken (status ≠ geprueft).
15	//   einheit     string    z. B. "€/ha·a", "ct/kWh", "Rp./kWh", "kWh/kWp", "Anteil", "Jahre", "Text"
16	//   land        "DE" | "AT" | "CH" | "DACH" (DACH = gilt unverändert in allen drei Ländern)
17	//   quelle      { titel, url, art? }  url = Primärquelle (https) oder null bei eigener Einschätzung;
18	//                         art: "primaer" | "sekundaer" | "eigen" (optional, Standard "primaer")
19	//   abruf       ISO-Datum  wann die Quelle zuletzt eingesehen bzw. die Einschätzung getroffen wurde
20	//   gueltigAb   ISO-Datum | null
21	//   gueltigBis  ISO-Datum | null   (null = unbefristet bzw. bis zur nächsten Änderung)
22	//   status      "geprueft" | "zu_pruefen" | "entwurf" | "abgelaufen"
23	//                         geprueft   = Wert am Original (quelle.url) nachgeprüft
24	//                         zu_pruefen = Quelle genannt oder eigene Einschätzung, noch nicht am Original geprüft
25	//                         entwurf    = vorgeschlagen, nicht freigegeben (wird nie in Rechnern verwendet)
26	//                         abgelaufen = bewusst als veraltet markiert
27	//   pruefer     string    Rolle/Kürzel; solange die zweite Prüfperson (E6) fehlt: "… · Zweitprüfung TODO-E6"
28	//   klasse      "A" | "B" | "C"   siehe KLASSEN
29	//   notiz       string (optional)  Herleitung, Einschränkungen
30	// }
31	
32	export const LAENDER = ["DE", "AT", "CH", "DACH"];
33	export const STATUS = ["geprueft", "zu_pruefen", "entwurf", "abgelaufen"];
34	export const QUELLEN_ARTEN = ["primaer", "sekundaer", "eigen"];
35	
36	/**
37	 * Klassen (Masterplan H7, Abschnitt 12 „Klasse-A-Änderungen brauchen die zweite Person (E6)“):
38	 *  A  Recht, Förderung, Abgaben/Umlagen, Fristen – ein abgelaufener A-Wert wird nie als aktuell gezeigt,
39	 *     qa/fakten-check.mjs setzt das Gate dann auf ROT.
40	 *  B  Markt- und Statistikwerte mit externer Quelle (Ausschreibungsergebnisse, Destatis, PVGIS, Studien).
41	 *  C  Eigene Annahmen und Einschätzungen (Spannen, Rechenwerte) – immer als Orientierung kennzeichnen.
42	 */
43	export const KLASSEN = {
44	  A: "Recht, Förderung, Abgaben und Fristen",
45	  B: "Markt- und Statistikwert mit externer Quelle",
46	  C: "Eigene Annahme oder Einschätzung",
47	};
48	
49	export const STATUS_TEXT = {
50	  geprueft: "am Original geprüft",
51	  zu_pruefen: "Prüfung ausstehend",
52	  entwurf: "Entwurf",
53	  abgelaufen: "Stand abgelaufen, wird geprüft",
54	};
55	
56	/** Text, der für einen abgelaufenen Wert IMMER statt „aktuell“ erscheint (Masterplan H7) */
57	export const HINWEIS_ABGELAUFEN = "Stand abgelaufen, wird geprüft";
58	
59	const ISO = /^\d{4}-\d{2}-\d{2}$/;
60	const ID = /^[a-z0-9][A-Za-z0-9_.-]*$/;
61	
62	/** true für ein gültiges ISO-Datum JJJJ-MM-TT */
63	export function istIsoDatum(s) {
64	  if (typeof s !== "string" || !ISO.test(s)) return false;
65	  const d = new Date(`${s}T00:00:00Z`);
66	  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === s;
67	}
68	
69	/** Heute (oder ein übergebenes Datum) als ISO-Datum JJJJ-MM-TT */
70	export function isoHeute(heute = new Date()) {
71	  if (typeof heute === "string") return heute.slice(0, 10);
72	  return heute.toISOString().slice(0, 10);
73	}
74	
75	/**
76	 * Prüft einen Fakt gegen den Vertrag.
77	 * @returns {{ ok: boolean, fehler: string[], warnungen: string[] }}
78	 */
79	export function faktValidieren(f) {
80	  const fehler = [];
81	  const warnungen = [];
82	  if (!f || typeof f !== "object") return { ok: false, fehler: ["kein Objekt"], warnungen };
83	  const wo = typeof f.id === "string" ? `${f.id} (${f.land ?? "?"})` : "(ohne id)";
84	  const F = (t) => fehler.push(`${wo}: ${t}`);
85	  const W = (t) => warnungen.push(`${wo}: ${t}`);
86	
87	  if (typeof f.id !== "string" || !ID.test(f.id)) F("id fehlt oder ungültig");
88	  if (f.wert === undefined) F("wert fehlt");
89	  if (f.wert === null && f.status === "geprueft") F("wert null, aber status geprueft");
90	  if (typeof f.einheit !== "string" || !f.einheit.trim()) F("einheit fehlt");
91	  if (!LAENDER.includes(f.land)) F(`land muss ${LAENDER.join("|")} sein`);
92	
93	  const q = f.quelle;
94	  if (!q || typeof q !== "object" || typeof q.titel !== "string" || !q.titel.trim()) F("quelle.titel fehlt");
95	  else {
96	    if (q.art !== undefined && !QUELLEN_ARTEN.includes(q.art)) F(`quelle.art muss ${QUELLEN_ARTEN.join("|")} sein`);
97	    if (q.url !== null && q.url !== undefined && (typeof q.url !== "string" || !/^https:\/\//.test(q.url))) F("quelle.url muss mit https:// beginnen oder null sein");
98	    if (!q.url && f.status === "geprueft") F("status geprueft verlangt quelle.url (Primärquelle)");
99	    if (!q.url && q.art !== "eigen") W("Quelle ohne URL – Fundstelle nachtragen");
100	  }
101	
102	  if (!istIsoDatum(f.abruf)) F("abruf fehlt oder ist kein ISO-Datum");
103	  if (f.gueltigAb != null && !istIsoDatum(f.gueltigAb)) F("gueltigAb ist kein ISO-Datum");
104	  if (f.gueltigBis != null && !istIsoDatum(f.gueltigBis)) F("gueltigBis ist kein ISO-Datum");
105	  if (istIsoDatum(f.gueltigAb) && istIsoDatum(f.gueltigBis) && f.gueltigAb > f.gueltigBis) F("gueltigAb liegt nach gueltigBis");
106	  if (!STATUS.includes(f.status)) F(`status muss ${STATUS.join("|")} sein`);
107	  if (typeof f.pruefer !== "string" || !f.pruefer.trim()) F("pruefer fehlt (Rolle/Kürzel oder TODO-E6)");
108	  if (!(f.klasse in KLASSEN)) F("klasse muss A, B oder C sein");
109	  if (f.notiz !== undefined && typeof f.notiz !== "string") F("notiz muss Text sein");
110	  return { ok: fehler.length === 0, fehler, warnungen };
111	}
112	
113	/**
114	 * Ist der Fakt am Stichtag abgelaufen? (status "abgelaufen" oder gueltigBis vor `heute`)
115	 * @param {object} fakt
116	 * @param {Date|string} [heute] Date oder ISO-Datum; Standard: jetzt
117	 */
118	export function istAbgelaufen(fakt, heute = new Date()) {
119	  if (!fakt) return false;
120	  if (fakt.status === "abgelaufen") return true;
121	  return istIsoDatum(fakt.gueltigBis) && fakt.gueltigBis < isoHeute(heute);
122	}
123	
124	/** Gilt der Fakt am Stichtag schon? (gueltigAb erreicht oder nicht gesetzt) */
125	export function istInKraft(fakt, heute = new Date()) {
126	  return !fakt?.gueltigAb || fakt.gueltigAb <= isoHeute(heute);
127	}
128	
129	/**
130	 * Anzeige-Status eines Fakts für Komponenten und Berichte:
131	 * "abgelaufen" (nie als aktuell zeigen) · "entwurf" · "zu_pruefen" · "geprueft"
132	 */
133	export function anzeigeStatus(fakt, heute = new Date()) {
134	  if (istAbgelaufen(fakt, heute)) return "abgelaufen";
135	  return fakt?.status || "zu_pruefen";
136	}
137	
138	/** ISO-Datum als deutsches Datum „17.07.2026“ */
139	export function datumDe(iso) {
140	  if (!istIsoDatum(iso)) return "";
141	  const [j, m, t] = iso.split("-");
142	  return `${t}.${m}.${j}`;
143	}
144	
145	const MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"];
146	
147	/** ISO-Datum als „1. März 2025“ */
148	export function datumLang(iso) {
149	  if (!istIsoDatum(iso)) return "";
150	  const [j, m, t] = iso.split("-").map(Number);
151	  return `${t}. ${MONATE[m - 1]} ${j}`;
152	}
153	
154	/** ISO-Datum als „September 2026“ */
155	export function monatJahr(iso) {
156	  if (!istIsoDatum(iso)) return "";
157	  const [j, m] = iso.split("-").map(Number);
158	  return `${MONATE[m - 1]} ${j}`;
159	}
