1	// src/lib/fakten/register.js
2	//
3	// Faktenregister (Welle 2, Paket B1) – Zugriff auf alle Fakten (Vertrag: schema.js).
4	// Die Datenmodule unter daten/*.js werden NUR in index.js eingebunden; alle anderen
5	// Dateien greifen über index.js zu (Abnahme f: keine Importe aus daten/* außerhalb
6	// src/lib/fakten).
7	//
8	// Ein Datenmodul ist entweder ein Array von Fakten oder ein Objekt
9	//   { name, fakten: Fakt[], quellen?: { [gruppe]: { titel, url }[] } }.
10	// Zeitliche Versionen (z. B. Umlagen 2026 und 2027) sind derselbe id + land mit
11	// unterschiedlichem gueltigAb; fakt() wählt die am Stichtag geltende Version.
12	
13	import { faktValidieren, isoHeute, LAENDER } from "./schema.js";
14	
15	const normLand = (land) => {
16	  const l = String(land || "DE").toUpperCase();
17	  return LAENDER.includes(l) ? l : "DE";
18	};
19	
20	const kopie = (v) => (v !== null && typeof v === "object" ? structuredClone(v) : v);
21	
22	/**
23	 * Baut ein Register aus Datenmodulen (index.js nutzt es für die echten Daten,
24	 * Tests für eigene Testfakten).
25	 */
26	export function erstelleRegister(module = []) {
27	  const liste = [];
28	  const quellen = {};
29	  for (const m of module) {
30	    const name = Array.isArray(m) ? "(ohne Name)" : m?.name || "(ohne Name)";
31	    const fakten = Array.isArray(m) ? m : m?.fakten || [];
32	    for (const f of fakten) liste.push(Object.freeze({ ...f, herkunft: name }));
33	    if (!Array.isArray(m) && m?.quellen) {
34	      for (const [gruppe, eintraege] of Object.entries(m.quellen)) {
35	        const schluessel = `${m.land || "DACH"}:${gruppe}`;
36	        quellen[schluessel] = [...(quellen[schluessel] || []), ...eintraege];
37	      }
38	    }
39	  }
40	
41	  /** Alle Versionen eines Fakts für genau dieses Land (ohne Entwürfe, außer mitEntwurf) */
42	  const versionen = (id, land, mitEntwurf) =>
43	    liste.filter((f) => f.id === id && f.land === land && (mitEntwurf || f.status !== "entwurf"));
44	
45	  /** Am Stichtag geltende Version: spätestes gueltigAb ≤ Stichtag; sonst die früheste */
46	  const waehle = (kandidaten, stichtag) => {
47	    if (!kandidaten.length) return null;
48	    const tag = isoHeute(stichtag);
49	    const inKraft = kandidaten.filter((f) => !f.gueltigAb || f.gueltigAb <= tag);
50	    const sortiert = (inKraft.length ? inKraft : kandidaten).slice().sort((a, b) => String(a.gueltigAb || "").localeCompare(String(b.gueltigAb || "")));
51	    return inKraft.length ? sortiert[sortiert.length - 1] : sortiert[0];
52	  };
53	
54	  /**
55	   * Ein Fakt für ein Land. Fehlt er für das Land, gilt ein DACH-Fakt derselben id.
56	   * @param {string} id
57	   * @param {"DE"|"AT"|"CH"|"DACH"} [land="DE"]
58	   * @param {{ stichtag?: Date|string, mitEntwurf?: boolean }} [optionen]
59	   * @returns {object|null} eingefrorenes Fakt-Objekt (wert ggf. tief kopieren: faktWert)
60	   */
61	  function fakt(id, land = "DE", { stichtag = new Date(), mitEntwurf = false } = {}) {
62	    const l = normLand(land);
63	    return waehle(versionen(id, l, mitEntwurf), stichtag) || (l !== "DACH" ? waehle(versionen(id, "DACH", mitEntwurf), stichtag) : null);
64	  }
65	
66	  /** Nur der Wert (tiefe Kopie – Aufrufer dürfen ihn verändern, ohne das Register zu ändern); undefined, wenn es den Fakt nicht gibt */
67	  function faktWert(id, land = "DE", optionen) {
68	    const f = fakt(id, land, optionen);
69	    return f ? kopie(f.wert) : undefined;
70	  }
71	
72	  /**
73	   * Gefilterte Liste. land: genau dieses Land plus DACH-Fakten (mitDach=false schaltet das ab);
74	   * klasse: "A"|"B"|"C"; praefix: id-Anfang (z. B. "pacht."); status: ein Status.
75	   */
76	  function fakten({ land, klasse, praefix, status, mitDach = true } = {}) {
77	    const l = land ? normLand(land) : null;
78	    return liste.filter(
79	      (f) =>
80	        (!l || f.land === l || (mitDach && l !== "DACH" && f.land === "DACH")) &&
81	        (!klasse || f.klasse === klasse) &&
82	        (!praefix || f.id.startsWith(praefix)) &&
83	        (!status || f.status === status)
84	    );
85	  }
86	
87	  /** Alle Fakten aller Module */
88	  const alleFakten = () => liste.slice();
89	
90	  /** Quellenverzeichnis einer Gruppe (z. B. "allgemein", "dach") für ein Land, als Kopie */
91	  const quellenListe = (land, gruppe = "allgemein") => kopie(quellen[`${normLand(land)}:${gruppe}`] || []);
92	
93	  /** Vertragsprüfung aller Fakten plus Dubletten (id + land + gueltigAb) */
94	  function pruefen() {
95	    const fehler = [];
96	    const warnungen = [];
97	    const gesehen = new Map();
98	    for (const f of liste) {
99	      const v = faktValidieren(f);
100	      fehler.push(...v.fehler.map((t) => `[${f.herkunft}] ${t}`));
101	      warnungen.push(...v.warnungen.map((t) => `[${f.herkunft}] ${t}`));
102	      const k = `${f.id}|${f.land}|${f.gueltigAb || ""}`;
103	      if (gesehen.has(k)) fehler.push(`[${f.herkunft}] Dublette ${f.id} (${f.land}, gueltigAb ${f.gueltigAb || "–"}) – schon in ${gesehen.get(k)}`);
104	      else gesehen.set(k, f.herkunft);
105	    }
106	    return { ok: fehler.length === 0, fehler, warnungen, anzahl: liste.length };
107	  }
108	
109	  return { fakt, faktWert, fakten, alleFakten, quellenListe, pruefen };
110	}
111

1	// src/lib/fakten/pruefen.js
2	//
3	// Gate-Logik des Faktenregisters (Welle 2, Paket B1) – genutzt von qa/fakten-check.mjs
4	// (Schritt in npm run verify) und den Tests. Reine Funktion, keine Ein-/Ausgabe.
5	//
6	// ROT (Gate)   – Vertragsfehler (schema.js), Dubletten, Fakten ohne quelle oder abruf,
7	//                abgelaufene Fakten der Klasse A (Masterplan H7: nie als aktuell zeigen).
8	// WARNUNG      – abgelaufene Fakten der Klassen B/C, status "zu_pruefen", Quelle ohne URL.
9	
10	import { faktValidieren, istAbgelaufen, isoHeute } from "./schema.js";
11	
12	const kurz = (f) => ({ id: f.id, land: f.land, klasse: f.klasse, status: f.status, gueltigBis: f.gueltigBis ?? null, herkunft: f.herkunft ?? null });
13	
14	/**
15	 * @param {object[]} liste Fakten (z. B. alleFakten())
16	 * @param {{ heute?: Date|string }} [optionen]
17	 */
18	export function pruefeFakten(liste, { heute = new Date() } = {}) {
19	  const stichtag = isoHeute(heute);
20	  const vertragsfehler = [];
21	  const hinweise = [];
22	  const gesehen = new Map();
23	  for (const f of liste) {
24	    const v = faktValidieren(f);
25	    vertragsfehler.push(...v.fehler);
26	    hinweise.push(...v.warnungen);
27	    const k = `${f?.id}|${f?.land}|${f?.gueltigAb || ""}`;
28	    if (gesehen.has(k)) vertragsfehler.push(`Dublette ${f?.id} (${f?.land}, gueltigAb ${f?.gueltigAb || "–"})`);
29	    gesehen.set(k, true);
30	  }
31	  const ohneQuelle = liste.filter((f) => !f?.quelle || typeof f.quelle.titel !== "string" || !f.quelle.titel.trim()).map(kurz);
32	  const ohneAbruf = liste.filter((f) => !f?.abruf).map(kurz);
33	  const abgelaufen = liste.filter((f) => istAbgelaufen(f, stichtag));
34	  const abgelaufenA = abgelaufen.filter((f) => f.klasse === "A").map(kurz);
35	  const abgelaufenBC = abgelaufen.filter((f) => f.klasse !== "A").map(kurz);
36	  const zuPruefen = liste.filter((f) => f?.status === "zu_pruefen").map(kurz);
37	  const ohneUrl = liste.filter((f) => f?.quelle && !f.quelle.url && f.quelle.art !== "eigen").map(kurz);
38	
39	  const rot = vertragsfehler.length > 0 || ohneQuelle.length > 0 || ohneAbruf.length > 0 || abgelaufenA.length > 0;
40	  const zaehle = (schluessel) => liste.reduce((m, f) => ((m[f?.[schluessel]] = (m[f?.[schluessel]] || 0) + 1), m), {});
41	  return {
42	    stichtag,
43	    urteil: rot ? "ROT" : "GRÜN",
44	    ok: !rot,
45	    zusammenfassung: {
46	      fakten: liste.length,
47	      vertragsfehler: vertragsfehler.length,
48	      ohneQuelle: ohneQuelle.length,
49	      ohneAbruf: ohneAbruf.length,
50	      abgelaufenKlasseA: abgelaufenA.length,
51	      abgelaufenKlasseBC: abgelaufenBC.length,
52	      zuPruefen: zuPruefen.length,
53	      ohneUrl: ohneUrl.length,
54	      jeLand: zaehle("land"),
55	      jeKlasse: zaehle("klasse"),
56	      jeStatus: zaehle("status"),
57	    },
58	    vertragsfehler,
59	    ohneQuelle,
60	    ohneAbruf,
61	    abgelaufenA,
62	    warnungen: { abgelaufenBC, zuPruefen, ohneUrl, hinweise },
63	  };
64	}
