1	// src/lib/fakten/index.js
2	//
3	// Öffentliche Schnittstelle des Faktenregisters (Welle 2, Paket B1).
4	//   import { fakt, faktWert, fakten, alleFakten } from "@/lib/fakten";
5	// Datenmodule werden NUR hier eingebunden (Abnahme f: keine Importe aus daten/*
6	// außerhalb src/lib/fakten). Neue Datei unter daten/ → hier in DATENMODULE eintragen.
7	// Vertrag eines Fakts: ./schema.js.
8	
9	import { erstelleRegister } from "./register.js";
10	import de from "./daten/de.js";
11	import at from "./daten/at.js";
12	import ch from "./daten/ch.js";
13	// Paket FRI (Termine, Umlagen, Netzentgelte) – Dateien gehören FRI, hier nur eingebunden
14	import termineDe from "./daten/termine-de.js";
15	import termineAt from "./daten/termine-at.js";
16	import termineCh from "./daten/termine-ch.js";
17	import umlagenDe from "./daten/umlagen-de.js";
18	import umlagenAt from "./daten/umlagen-at.js";
19	import umlagenCh from "./daten/umlagen-ch.js";
20	import netzentgelteDe from "./daten/netzentgelte-de.js";
21	import netzentgelteAt from "./daten/netzentgelte-at.js";
22	import netzentgelteCh from "./daten/netzentgelte-ch.js";
23	// Paket B5 (Rechnungs-Check Gewerbestrom DE: Umlagen 2026, Stromsteuer, KAV, Börse SMARD)
24	import gewerbestromDe from "./daten/gewerbestrom-de.js";
25	// Paket B7 (EG-Software AT: ElWG-Regeln für Preisblatt, Wechsel-Check, White-Label)
26	import egAt from "./daten/eg-at.js";
27	// Paket B8 (Kommunal 2.0: Landesgesetze zur Gemeindebeteiligung DE)
28	import kommuneLaender from "./daten/kommune-laender.js";
29	// Paket GEBAEUDE (Welle 4: Gebäudestrom – Rechtsrahmen je Land und Rechenannahmen, keine Geldwerte)
30	import gebaeudestrom from "./daten/gebaeudestrom.js";
31	
32	export const DATENMODULE = [de, at, ch, termineDe, termineAt, termineCh, umlagenDe, umlagenAt, umlagenCh, netzentgelteDe, netzentgelteAt, netzentgelteCh, gewerbestromDe, egAt, kommuneLaender, gebaeudestrom];
33	
34	export const REGISTER = erstelleRegister(DATENMODULE);
35	
36	export const { fakt, faktWert, fakten, alleFakten, quellenListe } = REGISTER;
37	/** Vertragsprüfung aller Fakten (Dubletten, Pflichtfelder) – genutzt von qa/fakten-check.mjs und Tests */
38	export const registerPruefen = REGISTER.pruefen;
39	
40	export { erstelleRegister } from "./register.js";
41	export * from "./schema.js";
42	export * from "./waehrung.js";
43	export { pruefeFakten } from "./pruefen.js";
